node <<'NODE'
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const NOTION_TOKEN = process.env.NOTION_TOKEN;
const NOTION_DB = process.env.NOTION_PROJECTS_DB_ID;
const LINEAR_API_KEY = process.env.LINEAR_API_KEY;
const STATE_PATH = process.env.N8N_SYNC_STATE_PATH || '/home/node/.n8n-files/notion-linear-sync/sync_state.json';
const CONFLICT_STRATEGY = process.env.CONFLICT_STRATEGY || 'last-write-wins';
const NOTION_VERSION = '2022-06-28';

function sha(data) {
  return crypto.createHash('sha256').update(JSON.stringify(data)).digest('hex').slice(0, 16);
}

function ensureStateFile() {
  const dir = path.dirname(STATE_PATH);
  fs.mkdirSync(dir, { recursive: true });
  if (!fs.existsSync(STATE_PATH)) {
    fs.writeFileSync(STATE_PATH, JSON.stringify({ version: 1, entities: { project: [], milestone: [], task: [] } }, null, 2));
  }
}

function loadState() {
  ensureStateFile();
  try {
    return JSON.parse(fs.readFileSync(STATE_PATH, 'utf8'));
  } catch (error) {
    return { version: 1, entities: { project: [], milestone: [], task: [] } };
  }
}

function saveState(state) {
  ensureStateFile();
  fs.writeFileSync(STATE_PATH, JSON.stringify(state, null, 2));
}

function upsertProjectState(state, record) {
  const bucket = state.entities.project || [];
  state.entities.project = bucket.filter((entry) => !(entry.notionId && entry.notionId === record.notionId) && !(entry.linearId && entry.linearId === record.linearId));
  state.entities.project.push(record);
}

async function notionRequest(endpoint, options = {}) {
  const response = await fetch(`https://api.notion.com/v1${endpoint}`, {
    ...options,
    headers: {
      Authorization: `Bearer ${NOTION_TOKEN}`,
      'Notion-Version': NOTION_VERSION,
      'Content-Type': 'application/json',
      ...(options.headers || {})
    }
  });
  const body = await response.json();
  if (!response.ok) throw new Error(`Notion ${endpoint} failed: ${response.status} ${JSON.stringify(body)}`);
  return body;
}

async function linearRequest(query, variables = {}) {
  const response = await fetch('https://api.linear.app/graphql', {
    method: 'POST',
    headers: {
      Authorization: LINEAR_API_KEY,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ query, variables })
  });
  const body = await response.json();
  if (!response.ok || body.errors) throw new Error(`Linear request failed: ${JSON.stringify(body.errors || body)}`);
  return body.data;
}

function richText(value) {
  return value ? [{ text: { content: value } }] : [];
}

function readTitle(prop) {
  return (prop?.title || []).map((entry) => entry.plain_text || entry.text?.content || '').join('').trim();
}

function readRichText(prop) {
  return (prop?.rich_text || []).map((entry) => entry.plain_text || entry.text?.content || '').join('').trim();
}

function readSelect(prop) {
  return prop?.select?.name || null;
}

function readDate(prop) {
  return prop?.date?.start || null;
}

function readCheckbox(prop) {
  return Boolean(prop?.checkbox);
}

function normalizeProjectStatusFromLinear(state) {
  return ({ planned: 'Predevelopment', started: 'Active', paused: 'Dormant', completed: 'Complete', canceled: 'Abandoned' })[state] || 'Active';
}

function normalizeProjectStatusToLinear(status) {
  return ({ Predevelopment: 'planned', Active: 'started', Dormant: 'paused', Complete: 'completed', Abandoned: 'canceled' })[status] || 'started';
}

function notionToUnified(page) {
  const props = page.properties || {};
  const record = {
    notionId: page.id,
    linearId: readRichText(props['linear id']),
    name: readTitle(props.title),
    description: readRichText(props['one liner']),
    status: readSelect(props.status) || 'Active',
    startedAt: readDate(props['started at']),
    updatedAt: page.last_edited_time,
    linearSync: readCheckbox(props['linear sync'])
  };
  record.contentHash = sha({ name: record.name, description: record.description || '', status: record.status, startedAt: record.startedAt || null });
  return record;
}

function linearToUnified(project) {
  const record = {
    notionId: null,
    linearId: project.id,
    name: project.name,
    description: project.description || '',
    status: normalizeProjectStatusFromLinear(project.state),
    linearState: project.state,
    startedAt: project.startDate || null,
    updatedAt: project.updatedAt,
    linearSync: true
  };
  record.contentHash = sha({ name: record.name, description: record.description || '', status: record.status, startedAt: record.startedAt || null });
  return record;
}

async function fetchNotionProjects() {
  let cursor;
  const records = [];
  do {
    const body = {
      page_size: 100,
      filter: { property: 'linear sync', checkbox: { equals: true } }
    };
    if (cursor) body.start_cursor = cursor;
    const response = await notionRequest(`/databases/${NOTION_DB}/query`, { method: 'POST', body: JSON.stringify(body) });
    records.push(...response.results.map(notionToUnified));
    cursor = response.has_more ? response.next_cursor : null;
  } while (cursor);
  return records;
}

async function fetchLinearProjects() {
  const data = await linearRequest(`query Projects { projects(first: 250) { nodes { id name description state startDate updatedAt } } }`);
  return (data.projects?.nodes || []).map(linearToUnified);
}

function getStateFor(state, notionId, linearId) {
  return (state.entities.project || []).find((entry) => (notionId && entry.notionId === notionId) || (linearId && entry.linearId === linearId)) || null;
}

function asMillis(value) {
  if (!value) return 0;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? 0 : date.getTime();
}

function chooseWinner(notionRecord, linearRecord, state) {
  if (!state) return asMillis(notionRecord.updatedAt) >= asMillis(linearRecord.updatedAt) ? 'notion' : 'linear';
  const notionChanged = asMillis(notionRecord.updatedAt) > asMillis(state.notionLastModified);
  const linearChanged = asMillis(linearRecord.updatedAt) > asMillis(state.linearLastModified);
  if (notionChanged && !linearChanged) return 'notion';
  if (linearChanged && !notionChanged) return 'linear';
  if (!notionChanged && !linearChanged) return 'none';
  if (CONFLICT_STRATEGY === 'notion-primary') return 'notion';
  if (CONFLICT_STRATEGY === 'linear-primary') return 'linear';
  return asMillis(notionRecord.updatedAt) >= asMillis(linearRecord.updatedAt) ? 'notion' : 'linear';
}

function notionProjectProperties(record) {
  return {
    title: { title: [{ text: { content: record.name } }] },
    'linear id': { rich_text: richText(record.linearId) },
    'linear sync': { checkbox: true },
    status: { select: { name: record.status || 'Active' } },
    'one liner': { rich_text: richText(record.description || '') },
    'started at': record.startedAt ? { date: { start: record.startedAt } } : undefined
  };
}

async function applyLinearCreateFromNotion(record) {
  const data = await linearRequest(`mutation CreateProject($input: ProjectCreateInput!) { projectCreate(input: $input) { success project { id updatedAt state startDate } } }`, { input: { name: record.name, description: record.description || undefined, state: normalizeProjectStatusToLinear(record.status), startDate: record.startedAt || undefined } });
  const project = data.projectCreate.project;
  await notionRequest(`/pages/${record.notionId}`, { method: 'PATCH', body: JSON.stringify({ properties: { 'linear id': { rich_text: richText(project.id) } } }) });
  return { ...record, linearId: project.id, updatedAt: record.updatedAt, linearUpdatedAt: project.updatedAt };
}

async function applyLinearUpdateFromNotion(record, linearId) {
  const data = await linearRequest(`mutation UpdateProject($id: String!, $input: ProjectUpdateInput!) { projectUpdate(id: $id, input: $input) { success project { id updatedAt state startDate } } }`, { id: linearId, input: { name: record.name, description: record.description || undefined, state: normalizeProjectStatusToLinear(record.status), startDate: record.startedAt || undefined } });
  return data.projectUpdate.project;
}

async function applyNotionCreateFromLinear(record) {
  const page = await notionRequest('/pages', { method: 'POST', body: JSON.stringify({ parent: { database_id: NOTION_DB }, properties: Object.fromEntries(Object.entries(notionProjectProperties(record)).filter(([, value]) => value !== undefined)) }) });
  return page;
}

async function applyNotionUpdateFromLinear(record, notionId) {
  const page = await notionRequest(`/pages/${notionId}`, { method: 'PATCH', body: JSON.stringify({ properties: Object.fromEntries(Object.entries(notionProjectProperties(record)).filter(([, value]) => value !== undefined)) }) });
  return page;
}

(async () => {
  const state = loadState();
  const notionProjects = await fetchNotionProjects();
  const linearProjects = await fetchLinearProjects();
  const linearById = new Map(linearProjects.map((record) => [record.linearId, record]));
  const touchedLinearIds = new Set();
  const summary = { success: true, entityType: 'project', scanned: notionProjects.length + linearProjects.length, createdToLinear: 0, updatedToLinear: 0, createdToNotion: 0, updatedToNotion: 0, errors: [] };

  for (const notionRecord of notionProjects) {
    const linearRecord = notionRecord.linearId ? linearById.get(notionRecord.linearId) : undefined;
    if (!linearRecord) {
      try {
        const created = await applyLinearCreateFromNotion(notionRecord);
        upsertProjectState(state, { entityType: 'project', notionId: notionRecord.notionId, linearId: created.linearId, notionLastModified: notionRecord.updatedAt, linearLastModified: created.linearUpdatedAt, contentHash: notionRecord.contentHash, lastSynced: new Date().toISOString() });
        summary.createdToLinear += 1;
      } catch (error) {
        summary.success = false;
        summary.errors.push(`create linear from notion ${notionRecord.notionId}: ${error.message}`);
      }
      continue;
    }

    touchedLinearIds.add(linearRecord.linearId);
    const stateRecord = getStateFor(state, notionRecord.notionId, linearRecord.linearId);
    if (notionRecord.contentHash === linearRecord.contentHash) {
      upsertProjectState(state, { entityType: 'project', notionId: notionRecord.notionId, linearId: linearRecord.linearId, notionLastModified: notionRecord.updatedAt, linearLastModified: linearRecord.updatedAt, contentHash: notionRecord.contentHash, lastSynced: new Date().toISOString() });
      continue;
    }

    const winner = chooseWinner(notionRecord, linearRecord, stateRecord);
    if (winner === 'notion') {
      try {
        const updated = await applyLinearUpdateFromNotion(notionRecord, linearRecord.linearId);
        upsertProjectState(state, { entityType: 'project', notionId: notionRecord.notionId, linearId: linearRecord.linearId, notionLastModified: notionRecord.updatedAt, linearLastModified: updated.updatedAt, contentHash: notionRecord.contentHash, lastSynced: new Date().toISOString() });
        summary.updatedToLinear += 1;
      } catch (error) {
        summary.success = false;
        summary.errors.push(`update linear ${linearRecord.linearId}: ${error.message}`);
      }
    } else if (winner === 'linear') {
      try {
        const page = await applyNotionUpdateFromLinear(linearRecord, notionRecord.notionId);
        upsertProjectState(state, { entityType: 'project', notionId: notionRecord.notionId, linearId: linearRecord.linearId, notionLastModified: page.last_edited_time, linearLastModified: linearRecord.updatedAt, contentHash: linearRecord.contentHash, lastSynced: new Date().toISOString() });
        summary.updatedToNotion += 1;
      } catch (error) {
        summary.success = false;
        summary.errors.push(`update notion ${notionRecord.notionId}: ${error.message}`);
      }
    }
  }

  for (const linearRecord of linearProjects) {
    if (touchedLinearIds.has(linearRecord.linearId)) continue;
    try {
      const page = await applyNotionCreateFromLinear(linearRecord);
      upsertProjectState(state, { entityType: 'project', notionId: page.id, linearId: linearRecord.linearId, notionLastModified: page.last_edited_time, linearLastModified: linearRecord.updatedAt, contentHash: linearRecord.contentHash, lastSynced: new Date().toISOString() });
      summary.createdToNotion += 1;
    } catch (error) {
      summary.success = false;
      summary.errors.push(`create notion from linear ${linearRecord.linearId}: ${error.message}`);
    }
  }

  saveState(state);
  summary.status = summary.errors.length ? 'completed_with_errors' : 'success';
  summary.projectsCount = summary.createdToLinear + summary.updatedToLinear + summary.createdToNotion + summary.updatedToNotion;
  summary.details = summary.errors.length ? summary.errors.join(' | ').slice(0, 1900) : `Projects synced: ${summary.projectsCount}`;
  process.stdout.write(JSON.stringify(summary));
})().catch((error) => {
  process.stdout.write(JSON.stringify({ success: false, entityType: 'project', status: 'failed', projectsCount: 0, details: error.message.slice(0, 1900), errors: [error.message] }));
  process.exitCode = 1;
});
NODE

